+        ("HOME".into(), data.path().display().to_string()),
+        ("OC_TEST_ALLOW_LOOPBACK".into(), "1".into()),
+    ]);
+    let (app, guard, _) = application::spawn_with_env(a.path(), data.path(), env.clone())
+        .await
+        .unwrap();
